        /* **\u9AD8\u3055\u3092 vh \u3084 dvh \u3067\u6C7A\u3081\u306A\u3044\u3053\u3068\u3002** iPhone \u306E\u300C\u30A2\u30D7\u30EA\u5185\u30D6\u30E9\u30A6\u30B6\u300D\u3067\u306F\u3001\u3069\u3061\u3089\u3082\u898B\u3048\u3066\u3044\u308B\u9AD8\u3055\u3068
           \u98DF\u3044\u9055\u3046\u3053\u3068\u304C\u3042\u308A\u3001\u7D19\u306E\u8DB3\u3082\u3068\uFF08\u6C7A\u5B9A\u306E\u30DC\u30BF\u30F3\uFF09\u304C\u753B\u9762\u306E\u5916\u3078\u62BC\u3057\u51FA\u3055\u308C\u308B\u3002\u4E0A\u4E0B\u3092 0 \u3067\u7559\u3081\u308C\u3070\u3001
           \u3044\u3064\u3067\u3082\u898B\u3048\u3066\u3044\u308B\u9AD8\u3055\u3074\u3063\u305F\u308A\u306B\u306A\u308B\uFF08\u59C9\u59B9\u30A2\u30D7\u30EA My\u624B\u5E33 \u3068\u540C\u3058\uFF09 */
